package notification.core.artifact;import notification.core.recipient.Recipient;import java.util.Collections;import java.util.HashMap;import java.util.Map;/** * Default implementation of PersonalizationArtifact. * * Stores personalization variables for each recipient. * * Example: * * Recipient: user1@example.com * Variables: *   name  -> Bhanu *   order -> ORD123 */public class DefaultPersonalizationArtifact        implements PersonalizationArtifact {    private final Map<String, Map<String, String>> variablesByRecipient;    /**     * Creates an empty personalization artifact.     */    public DefaultPersonalizationArtifact() {        this.variablesByRecipient = new HashMap<>();    }    /**     * Creates personalization artifact with initial data.     *     * @param variablesByRecipient personalization variables grouped by recipient ID     */    public DefaultPersonalizationArtifact(            Map<String, Map<String, String>> variablesByRecipient) {        this.variablesByRecipient = new HashMap<>();        if (variablesByRecipient != null) {            this.variablesByRecipient.putAll(                    variablesByRecipient            );        }    }    /**     * Adds a personalization variable for a recipient.     *     * @param recipient recipient     * @param key variable name     * @param value variable value     */    public void addVariable(            Recipient recipient,            String key,            String value) {        if (recipient == null) {            throw new IllegalArgumentException(                    "Recipient cannot be null"            );        }        if (key == null || key.trim().isEmpty()) {            throw new IllegalArgumentException(                    "Personalization key cannot be null or empty"            );        }        variablesByRecipient                .computeIfAbsent(                        recipient.id(),                        id -> new HashMap<>()                )                .put(key, value);    }    /**     * Adds multiple personalization variables for a recipient.     *     * @param recipient recipient     * @param variables personalization variables     */    public void addVariables(            Recipient recipient,            Map<String, String> variables) {        if (recipient == null) {            throw new IllegalArgumentException(                    "Recipient cannot be null"            );        }        if (variables == null || variables.isEmpty()) {            return;        }        variablesByRecipient                .computeIfAbsent(                        recipient.id(),                        id -> new HashMap<>()                )                .putAll(variables);    }    /**     * Returns personalization variables for a recipient.     *     * @param recipient recipient     * @return personalization variables     */    @Override    public Map<String, String> variablesFor(            Recipient recipient) {        if (recipient == null) {            return Collections.emptyMap();        }        Map<String, String> variables =                variablesByRecipient.get(recipient.id());        if (variables == null) {            return Collections.emptyMap();        }        return Collections.unmodifiableMap(variables);    }}